function showAuthMessage(message,type='info',target='authNotice'){
 const n=document.getElementById(target); if(!n){if(message) alert(message);return;} n.textContent=message||''; n.classList.toggle('hidden',!message);
 n.style.borderColor=type==='error'?'#b76a62':type==='success'?'#738b76':''; n.style.color=type==='error'?'#8b3f38':type==='success'?'#365c3d':'';
