function safeFileName(name='document'){return name.normalize('NFKD').replace(/[^\\w.\\-]+/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'').toLowerCase();}
async function uploadVerificationFile(userId,file,kind){
 if(!sqmSupabase||!file)return null; const path=`${userId}/${kind}/${Date.now()}-${safeFileName(file.name)}`;
 const {data,error}=await sqmSupabase.storage.from('company-verification').upload(path,file,{contentType:file.type||undefined,upsert:false}); if(error)throw error;
 const {error:rowError}=await sqmSupabase.from('company_verification_documents').insert({user_id:userId,document_type:kind,storage_path:data.path,original_name:file.name,mime_type:file.type||null,size_bytes:file.size||null}); if(rowError)throw rowError; return data.path;
}

