function esc(s){return String(s||'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}

function applyRoleRegistrationMode(){
  const pane=document.getElementById('registerPane');
  const fields=document.getElementById('registrationFields');
  const hasRole=['buyer','supplier','service'].includes(selectedRole);
  const isBuyer=selectedRole==='buyer';

  fields?.classList.toggle('hidden',!hasRole);
  pane?.classList.toggle('buyer-mode',isBuyer);

  document.querySelectorAll('#registerPane .corporate-only input, #registerPane .corporate-only select, #registerPane .corporate-only textarea, #registerPane .corporate-section input, #registerPane .corporate-section select, #registerPane .corporate-section textarea')
    .forEach(field=>{
      field.disabled=isBuyer;
      if(isBuyer && field.type==='file') field.value='';
    });
}

function openAuth(mode){
  setTimeout(applyRoleRegistrationMode,0);document.getElementById('authModal').classList.add('show');switchAuth(mode)}
