async function register(){
  if(!['buyer','supplier','service'].includes(selectedRole)){
    showAuthMessage('Devam etmek için önce hesap türünüzü seçin.','error');
    return;
  }
  if(!requireSupabase()) return;

  const termsBox=document.getElementById('termsConsent');
  const kvkkBox=document.getElementById('kvkkNotice');
  const marketingBox=document.getElementById('marketingConsent');

  if(termsBox && !termsBox.checked){
    showAuthMessage('Kayıt olmak için Kullanım Koşulları’nı kabul etmelisiniz.','error');
    return;
  }
  if(kvkkBox && !kvkkBox.checked){
    showAuthMessage('Kayıt olmak için KVKK Aydınlatma Metni’ni okuduğunuzu onaylamalısınız.','error');
    return;
  }

  const role=normalizedRole(selectedRole);
  const isBuyer=role==='buyer';

  const common={
    full_name:document.getElementById('regName').value.trim(),
    email:document.getElementById('regEmail').value.trim().toLowerCase(),
    password:document.getElementById('regPassword').value,
    role
  };

  if(!common.full_name){
    showAuthMessage('Ad Soyad alanını doldurun.','error');
    return;
  }
  if(!common.email){
    showAuthMessage('E-posta alanını doldurun.','error');
    return;
  }
  if(common.password.length<8){
    showAuthMessage('Şifre en az 8 karakter olmalı.','error');
    return;
  }

  const company=isBuyer ? {} : {
    legal_type:document.getElementById('regLegalType').value,
    activity_type:document.getElementById('regCompanyType').value,
    legal_name:document.getElementById('regLegalName').value.trim(),
    tax_no:document.getElementById('regTaxNo').value.trim(),
    tax_office:document.getElementById('regTaxOffice').value.trim(),
    mersis_no:document.getElementById('regMersisNo').value.trim(),
    registry_no:document.getElementById('regRegistryNo').value.trim(),
    country:document.getElementById('regCountry').value.trim(),
    city:document.getElementById('regCity').value.trim(),
    company_address:document.getElementById('regCompanyAddress').value.trim(),
    authorized_name:document.getElementById('regAuthorizedName').value.trim(),
    authorized_title:document.getElementById('regAuthorizedTitle').value.trim(),
    corporate_email:document.getElementById('regCorporateEmail').value.trim().toLowerCase(),
    phone:document.getElementById('regPhone').value.trim(),
    website:document.getElementById('regWebsite').value.trim()
  };

  if(!isBuyer){
    const required=[
      ['Şirket Hukuki Türü',company.legal_type],
      ['Faaliyet Türü',company.activity_type],
      ['Ticari Unvan',company.legal_name],
      ['Vergi Numarası',company.tax_no],
      ['Vergi Dairesi',company.tax_office],
      ['Ülke',company.country],
      ['Şehir',company.city],
      ['Firma Adresi',company.company_address],
      ['Yetkili Ad Soyad',company.authorized_name],
      ['Yetkili Görevi',company.authorized_title],
      ['Kurumsal E-posta',company.corporate_email],
      ['Telefon',company.phone]
    ];
    const missing=required.find(([,value])=>!value);
    if(missing){
      showAuthMessage(`${missing[0]} alanını doldurun.`,'error');
      return;
    }
  }

  const mainDoc=isBuyer ? null : (document.getElementById('regCompanyDocument')?.files?.[0]||null);
  const extraDoc=isBuyer ? null : (document.getElementById('regAdditionalDocument')?.files?.[0]||null);

  if(!isBuyer && !mainDoc){
    showAuthMessage('Firma doğrulama belgesini seçin.','error');
    return;
  }

  const submit=document.querySelector('#registerPane > .btn.primary');
  const oldText=submit?.textContent;
  if(submit){submit.disabled=true;submit.textContent='Hesap oluşturuluyor...';}
  showAuthMessage('');

  try{
    const metadata={
      ...common,
      ...company,
      terms_accepted:true,
      kvkk_acknowledged:true,
      marketing_consent:!!marketingBox?.checked,
      consented_at:new Date().toISOString()
    };
    delete metadata.email;
    delete metadata.password;

    const {data,error}=await sqmSupabase.auth.signUp({
      email:common.email,
      password:common.password,
      options:{
        data:metadata,
        emailRedirectTo:window.location.origin+window.location.pathname
      }
    });
    if(error) throw error;

    if(data.session && data.user){
      if(!isBuyer && mainDoc){
        try{
          await uploadVerificationFile(data.user.id,mainDoc,'company-document');
          if(extraDoc) await uploadVerificationFile(data.user.id,extraDoc,'additional-document');
        }catch(uploadError){
          console.error('Belge yükleme hatası:',uploadError);
          showAuthMessage('Hesap oluşturuldu ancak doğrulama belgesi yüklenemedi. Giriş yaptıktan sonra tekrar yüklenmesi gerekecek.','error');
        }
      }

      currentUser=await loadSupabaseCurrentUser(data.user);
      closeModal('authModal');
      renderSession();
      document.getElementById('dashboard')?.scrollIntoView({behavior:'smooth'});
      return;
    }

    showAuthMessage(
      isBuyer
        ? 'Alıcı hesabınız oluşturuldu. E-posta adresinize gelen doğrulama bağlantısını açın; ardından giriş yapabilirsiniz.'
        : 'Firma hesabınız oluşturuldu. E-posta adresinize gelen doğrulama bağlantısını açın; ardından giriş yapabilirsiniz.',
      'success'
    );
  }catch(err){
    console.error(err);
    const msg=(err?.message||'').toLowerCase();
    const friendly=msg.includes('already registered')
      ? 'Bu e-posta adresiyle daha önce hesap oluşturulmuş.'
      : msg.includes('password')
      ? 'Şifre güvenlik kurallarını karşılamıyor.'
      : 'Üyelik oluşturulamadı. Bilgileri kontrol edip tekrar deneyin.';
    showAuthMessage(friendly,'error');
  }finally{
    if(submit){submit.disabled=false;submit.textContent=oldText||'Üyeliği Oluştur';}
  }
}
