}
function goToRequest(stone='',supplier=''){
  if(stone) document.getElementById('reqStone').value=stone;
  selectedSupplier=supplier;
  if(supplier){
    document.getElementById('reqAudience').value='Seçtiğim firma';
    document.getElementById('reqNotes').value=`Teklif özellikle ${supplier} firmasından isteniyor.`;
  }
  document.getElementById('requestFormSection').scrollIntoView({behavior:'smooth'});
}
function submitRequest(){
  if(!currentUser){openAuth('login');return}
  if(currentUser.role!=='buyer'){
    const n=document.getElementById('requestNotice');
    n.textContent='Teklif talebi oluşturmak için alıcı hesabıyla giriş yapın.';
    n.classList.remove('hidden');return;
  }
  const stone=document.getElementById('reqStone').value.trim();
  const qty=document.getElementById('reqQty').value.trim();
  const destination=document.getElementById('reqDestination').value.trim();
  if(!stone||!qty||!destination){
    const n=document.getElementById('requestNotice');
    n.textContent='Taş/ürün, miktar ve teslim yeri zorunlu.';
    n.classList.remove('hidden');return;
  }
  requests.unshift({
    id:Date.now(),owner:currentUser.company,stone,
    format:document.getElementById('reqFormat').value,
    qty,unit:document.getElementById('reqUnit').value,
    thickness:document.getElementById('reqThickness').value,
    finish:document.getElementById('reqFinish').value,
    destination,
    audience:document.getElementById('reqAudience').value,
    notes:document.getElementById('reqNotes').value,
    status:'Açık',matches:Math.floor(Math.random()*8)+4
  });
  saveAll();renderRequests();renderDashboard();
  const n=document.getElementById('requestNotice');
  n.textContent='Talebiniz yayınlandı. Uygun firmalarla demo eşleştirmesi yapıldı.';
  n.classList.remove('hidden');
}
