let pendingProductPhotos=[];
let pendingPortfolioVideo=null;
let pendingPortfolioPdf=null;

function handlePortfolioVideo(event){
  const f=event.target.files && event.target.files[0];
  pendingPortfolioVideo=null;
  const status=document.getElementById('videoStatus');
  if(!f){if(status) status.textContent='';return;}

  const allowed=['video/mp4','video/webm','video/quicktime'];
  if(!allowed.includes(f.type)){
    alert('Video MP4, WEBM veya MOV formatında olmalıdır.');
    event.target.value='';
    if(status) status.textContent='';
    return;
  }
  pendingPortfolioVideo={name:f.name,type:f.type,size:f.size};
  if(status) status.textContent='Seçildi: '+f.name;
}

function handlePortfolioPdf(event){
  const f=event.target.files && event.target.files[0];
  pendingPortfolioPdf=null;
  const status=document.getElementById('pdfStatus');
  if(!f){if(status) status.textContent='';return;}

  if(f.type!=='application/pdf' && !f.name.toLowerCase().endsWith('.pdf')){
    alert('Teknik doküman PDF formatında olmalıdır.');
    event.target.value='';
    if(status) status.textContent='';
    return;
  }
  pendingPortfolioPdf={name:f.name,type:'application/pdf',size:f.size};
  if(status) status.textContent='Seçildi: '+f.name;
}
async function compressImage(file,max=900,quality=.76){
  return new Promise((resolve,reject)=>{const r=new FileReader();r.onerror=reject;r.onload=()=>{const img=new Image();img.onload=()=>{let w=img.width,h=img.height;if(Math.max(w,h)>max){const k=max/Math.max(w,h);w=Math.round(w*k);h=Math.round(h*k)}const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);resolve(c.toDataURL('image/jpeg',quality))};img.onerror=reject;img.src=r.result};r.readAsDataURL(file)})
}
async function handleProductPhotos(event){
  const selected = Array.from(event.target.files || []);

  if(selected.length < 3){
    alert('Ürün yayınlamak için en az 3 fotoğraf seçmelisiniz.');
    event.target.value = '';
    pendingProductPhotos = [];
    renderPhotoPreview();
    return;
  }

  if(selected.length > 10){
    alert('Bir ürün için en fazla 10 fotoğraf yükleyebilirsiniz.');
    event.target.value = '';
    pendingProductPhotos = [];
    renderPhotoPreview();
    return;
  }

  pendingProductPhotos = [];
  for(const file of selected){
    try{
      const img = await compressImage(file, 800, .68);
      pendingProductPhotos.push(img);
    }catch(err){
      console.error(err);
    }
  }
  renderPhotoPreview();
}

function renderPhotoPreview(){
  const el = document.getElementById('photoPreview');
  if(!el) return;
  el.innerHTML = pendingProductPhotos.map((src,i) =>
    `<div class="photo-thumb">
      <img src="${src}" alt="Ürün fotoğrafı ${i+1}">
      <button type="button" onclick="removePendingPhoto(${i})">×</button>
    </div>`
  ).join('');
}

function removePendingPhoto(i){pendingProductPhotos.splice(i,1);renderPhotoPreview()}
