    ['regAuthorizedTitle','Yetkili kişinin görevini girin.'],
    ['regCorporateEmail','Kurumsal e-posta adresini girin.'],
    ['regPhone','Telefon numarasını girin.']
  ];
  for(const [id,msg] of required){
    const el=document.getElementById(id);
    if(el && !String(el.value||'').trim()){
