  if(!consent){ alert('İletişim bilgilerinizin satıcıyla paylaşılmasına onay vermelisiniz.'); return; }

  const leads=JSON.parse(localStorage.getItem('sqm_contact_leads')||'[]');
  leads.unshift({
    id:'LEAD-'+Date.now(),
    productId,
    name,
    company,
    email:shareEmail?email:'',
    phone:sharePhone?phone:'',
    source:'Marble Borsa',
    status:'Yeni',
