      if(!q) return;
      const active=document.querySelector('.sqm-panel.active') || document.querySelector('.sqm-panel');
      if(!active) return;
      const candidates=[...active.querySelectorAll('.card,.supplier,.product-card,.request-card,.category-tile,a')];
      let found=false;
      candidates.forEach(el=>{
        const match=(el.textContent||'').toLowerCase().includes(q);
