const MB_ORIGINAL_TEXT = new WeakMap();
const MB_ORIGINAL_PLACEHOLDER = new WeakMap();

function mbNormalizeText(s) {
  return (s || '').replace(/\s+/g,' ').trim();
}

function mbTranslateTextNode(node, dict) {
  if(!MB_ORIGINAL_TEXT.has(node)) MB_ORIGINAL_TEXT.set(node,node.nodeValue);
  const original=MB_ORIGINAL_TEXT.get(node);
  const key=mbNormalizeText(original);
  if(!key) return;
  if(dict && dict[key]) {
    const lead=(original.match(/^\s*/)||[''])[0];
    const trail=(original.match(/\s*$/)||[''])[0];
    node.nodeValue=lead+dict[key]+trail;
  } else {
    node.nodeValue=original;
  }
}

function setLanguage(lang) {
  if(!['tr','en','zh','ar'].includes(lang)) lang='tr';
  const dict=lang==='tr' ? null : MB_TRANSLATIONS[lang];

  document.documentElement.lang=lang;
  document.documentElement.dir=lang==='ar' ? 'rtl' : 'ltr';
  document.body.classList.toggle('lang-ar',lang==='ar');

  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{
    acceptNode(node){
      const p=node.parentElement;
      if(!p || ['SCRIPT','STYLE','NOSCRIPT'].includes(p.tagName)) return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }
  });
  const nodes=[];
  while(walker.nextNode()) nodes.push(walker.currentNode);
  nodes.forEach(n=>mbTranslateTextNode(n,dict));

  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{
    if(!MB_ORIGINAL_PLACEHOLDER.has(el)) MB_ORIGINAL_PLACEHOLDER.set(el,el.placeholder);
    const original=MB_ORIGINAL_PLACEHOLDER.get(el);
    el.placeholder=(dict && dict[original]) ? dict[original] : original;
  });

  document.querySelectorAll('.mb-language-switcher button').forEach(b=>b.classList.toggle('active',b.dataset.lang===lang));
  try{localStorage.setItem('mb_language',lang)}catch(e){}
}

document.addEventListener('click',e=>{
  const btn=e.target.closest('.mb-language-switcher [data-lang]');
  if(!btn) return;
  setLanguage(btn.dataset.lang);
});

document.addEventListener('DOMContentLoaded',()=>{
  let lang='tr';
  try{lang=localStorage.getItem('mb_language')||'tr'}catch(e){}
  setLanguage(lang);
});

