(function(){
 const SIZE=10; let page=1;
 const getRows=()=>Array.from(document.querySelectorAll(".mb-dir-list .mb-dir-row"));
 const norm=s=>(s||"").toLocaleLowerCase("tr-TR").trim();
 function render(){
   const q=norm(document.getElementById("mbCompanySearch")?.value);
   const city=norm(document.getElementById("mbCompanyCity")?.value);
   const all=getRows();
   const list=all.filter(r=>(!q||norm(r.textContent).includes(q))&&(!city||norm(r.textContent).includes(city)))
     .sort((a,b)=>(a.querySelector(".mb-dir-main strong")?.textContent||"").localeCompare(b.querySelector(".mb-dir-main strong")?.textContent||"","tr"));
   const pages=Math.max(1,Math.ceil(list.length/SIZE)); page=Math.min(page,pages);
   all.forEach(r=>r.style.display="none");
   list.slice((page-1)*SIZE,page*SIZE).forEach(r=>r.style.display="grid");
   const box=document.getElementById("mbDirPagination"); if(!box)return;
   box.innerHTML="";
   const add=(txt,p,disabled,active)=>{const b=document.createElement("button");b.textContent=txt;b.disabled=disabled;if(active)b.className="active";b.onclick=()=>{page=p;render()};box.appendChild(b)};
   add("‹ Önceki",page-1,page===1,false);
   for(let i=1;i<=pages;i++)add(String(i),i,false,i===page);
   const s=document.createElement("span");s.textContent=list.length+" firma";box.appendChild(s);
   add("Sonraki ›",page+1,page===pages,false);
 }
 document.addEventListener("DOMContentLoaded",render);
 document.addEventListener("input",e=>{if(e.target.id==="mbCompanySearch"){page=1;setTimeout(render,0)}},true);
 document.addEventListener("change",e=>{if(e.target.id==="mbCompanyCity"){page=1;setTimeout(render,0)}},true);
