(function(){
 const PAGE_SIZE=10;
 let page=1;

 function norm(s){return (s||"").toLocaleLowerCase("tr-TR").trim();}
 function nameOf(row){return row.querySelector(".mb-dir-main strong")?.textContent.trim()||"";}

 function renderFirmDirectory(){
   const listBox=document.querySelector(".mb-dir-list");
   const pager=document.getElementById("mbDirPagination");
   if(!listBox||!pager)return;

   const q=norm(document.getElementById("mbCompanySearch")?.value);
   const city=norm(document.getElementById("mbCompanyCity")?.value);

   // Sort ALL rows by company name, then physically reorder them in DOM.
   const all=Array.from(listBox.querySelectorAll(".mb-dir-row"))
     .sort((a,b)=>nameOf(a).localeCompare(nameOf(b),"tr-TR",{sensitivity:"base"}));
   all.forEach(row=>listBox.appendChild(row));

   const filtered=all.filter(row=>{
     const text=norm(row.textContent);
     return (!q||text.includes(q))&&(!city||text.includes(city));
   });

   // Number according to the actual filtered/sorted order: 01,02,03...
   filtered.forEach((row,i)=>{
     const no=row.querySelector(".mb-dir-no");
     if(no) no.textContent=String(i+1).padStart(2,"0");
   });

   const pages=Math.max(1,Math.ceil(filtered.length/PAGE_SIZE));
   page=Math.max(1,Math.min(page,pages));

   all.forEach(row=>row.style.setProperty("display","none","important"));
   filtered.slice((page-1)*PAGE_SIZE,page*PAGE_SIZE)
     .forEach(row=>row.style.setProperty("display","grid","important"));

   pager.innerHTML="";
   function add(label,target,disabled,active){
     const b=document.createElement("button");
     b.type="button"; b.textContent=label; b.disabled=disabled;
     if(active)b.classList.add("active");
     b.addEventListener("click",function(ev){
       ev.preventDefault(); ev.stopPropagation();
       page=target; renderFirmDirectory();
     });
     pager.appendChild(b);
   }
   add("‹ Önceki",page-1,page===1,false);
   for(let i=1;i<=pages;i++) add(String(i),i,false,i===page);
   const info=document.createElement("span");
   info.textContent=filtered.length+" firma";
   pager.appendChild(info);
   add("Sonraki ›",page+1,page===pages,false);
 }

 function resetAndRender(){page=1;setTimeout(renderFirmDirectory,0);}

 // Run after every older DOMContentLoaded handler so this becomes source of truth.
 window.addEventListener("load",function(){setTimeout(renderFirmDirectory,50);});
 document.addEventListener("input",function(e){
   if(e.target?.id==="mbCompanySearch"){
     e.stopImmediatePropagation(); resetAndRender();
   }
 },true);
 document.addEventListener("change",function(e){
   if(e.target?.id==="mbCompanyCity" || e.target?.id==="mbCompanyType"){
     e.stopImmediatePropagation(); resetAndRender();
   }
 },true);

 window.renderFirmDirectory=renderFirmDirectory;
})();

(function(){
 function initStoneDirectory(){
  var grid=document.getElementById('mbStoneGrid'); if(!grid || grid.dataset.ready==='1') return;
  grid.dataset.ready='1';
  var search=document.getElementById('mbStoneSearch'), type=document.getElementById('mbStoneType'), color=document.getElementById('mbStoneColor'),
      city=document.getElementById('mbStoneCity'), format=document.getElementById('mbStoneFormat'), sort=document.getElementById('mbStoneSort'),
      clear=document.getElementById('mbStoneClear'), count=document.getElementById('mbStoneCount'), empty=document.getElementById('mbStoneEmpty');
  var cards=Array.from(grid.querySelectorAll('.mb-stone-card'));
  function norm(v){return (v||'').toLocaleLowerCase('tr-TR');}
  function apply(){
   var q=norm(search.value), t=norm(type.value), c=norm(color.value), ci=norm(city.value), f=norm(format.value);
   var visible=cards.filter(function(card){
    var ok=(!q || norm(card.dataset.name).includes(q))&&(!t||norm(card.dataset.type)===t)&&(!c||norm(card.dataset.color).includes(c))&&(!ci||norm(card.dataset.city)===ci)&&(!f||norm(card.dataset.format).includes(f));
    card.hidden=!ok; return ok;
   });
   var ordered=visible.slice();
   if(sort.value==='suppliers') ordered.sort(function(a,b){return Number(b.dataset.suppliers)-Number(a.dataset.suppliers)});
   if(sort.value==='az') ordered.sort(function(a,b){return (a.dataset.name||'').localeCompare(b.dataset.name||'','tr')});
   ordered.forEach(function(card){grid.appendChild(card)});
   count.textContent=visible.length+' taş listeleniyor'; empty.hidden=visible.length!==0;
  }
  [search,type,color,city,format,sort].forEach(function(el){el.addEventListener(el===search?'input':'change',apply)});
  clear.addEventListener('click',function(){search.value='';type.value='';color.value='';city.value='';format.value='';sort.value='default';apply()});
  apply();
 }
 if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',initStoneDirectory); else initStoneDirectory();
 setTimeout(initStoneDirectory,300);
})();

